def label_of(key):
    """(origin, run label) of an InventoryUpdate key: excel-<job>-<row>, '<apiag-cloud label> · <id>[ retirado]' or a manual update id."""
    if key.startswith('excel-') and key.count('-') >= 6:
        return 'excel', key.rsplit('-', 1)[0]
    if key.startswith('apiag-cloud') and ' · ' in key:
        return 'apiag', key.split(' · ')[0]
    return 'manual', key


def rebuild(apps, schema_editor):
    """The ledger before it existed: every stock entry gets its supplier, and the loads already recorded (Excel imports, apiag-cloud
    pulls, manual updates, read from InventoryUpdate) become runs that created items or moved their units. The fields they changed were
    never kept, so those runs say so (rebuilt)."""
