    entries = {reference: (pk, quantity, direction, after, actor) for reference, pk, quantity, direction, after, actor in
               StockEntry.objects.filter(kind='sync').values_list('reference', 'pk', 'quantity', 'direction', 'reported_after', 'actor_id')}
    jobs = {str(pk): (owner, filename) for pk, owner, filename in Job.objects.values_list('pk', 'owner_id', 'filename')}
    runs, seen_items, seen_pairs, changes, counts = {}, set(), set(), [], {}
    for supplier, key, item, created_at in InventoryUpdate.objects.order_by('created_at', 'pk').values_list('supplier_id', 'key', 'item_id', 'created_at').iterator():
        first = item not in seen_items
        seen_items.add(item)
        entry = entries.get(key)
        if not first and entry is None:
            continue  # a field change, an unchanged row or a dedupe: what it changed was never kept
        origin, label = label_of(key)
        run = runs.get((supplier, label))
        if run is None:
            job = jobs.get(label[len('excel-'):]) if origin == 'excel' else None
            run = InventoryRun.objects.create(supplier_id=supplier, origin=origin, label=label[:120], rebuilt=True, started_at=created_at,
                                              finished_at=created_at, import_job_id=label[len('excel-'):] if job else None,
                                              filename=(job[1] if job else '')[:255], actor_id=job[0] if job else (entry[4] if entry else None))
            runs[(supplier, label)] = run
            counts[run.pk] = {'created': 0, 'updated': 0, 'stock': 0, 'withdrawn': 0, 'credit_units': 0, 'debit_units': 0}
        elif run.actor_id is None and entry is not None and entry[4]:
            run.actor_id = entry[4]  # the run's first update may have created an item with no units, so no entry signed it
        run.finished_at = max(run.finished_at, created_at)
        if (run.pk, item) in seen_pairs:
            continue
        seen_pairs.add((run.pk, item))
        before = after = None
        if entry is not None:
            after = entry[3]
            before = after - entry[1] if entry[2] == 'credit' else after + entry[1]
            counts[run.pk]['credit_units' if after > before else 'debit_units'] += abs(after - before)
        elif first:
            before = after = 0
        action = 'created' if first else 'withdrawn' if key.endswith(' retirado') else 'stock'
        counts[run.pk][action] += 1
        changes.append(InventoryChange(run_id=run.pk, item_id=item, action=action, quantity_before=before, quantity_after=after,
                                       stock_entry_id=entry[0] if entry else None, created_at=created_at,
                                       fields={'reason': 'unseen'} if action == 'withdrawn' else {}))
        if len(changes) >= 1000:
            InventoryChange.objects.bulk_create(changes)
            changes = []
    InventoryChange.objects.bulk_create(changes)
